<input class="input" name="payment_method" value="<?=e($q['payment_method']??'')?>"></div><div class="field full"><label>Observaciones</label><textarea class="textarea" name="notes"><?=e($q['notes']??'')?></textarea></div></div></div></section><div class="actions"><button class="btn btn-primary">Guardar cambios</button></div></form></main></div></div></body></html>
